#include <iostream>
#include <string>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "correlation.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto n_vec = noarr::vector<'n'>();
constexpr auto m_vec = noarr::vector<'m'>();
constexpr auto p_vec = noarr::vector<'p'>();
constexpr auto q_vec = noarr::vector<'q'>();

struct tuning {
	// data: n x m  (rows: n, columns/features: m), column-major (n contiguous)
	// layout: scalar ^ n_vec ^ m_vec -> dims 'm' (outer), 'n' (inner/contiguous)
	DEFINE_PROTO_STRUCT(data_layout, n_vec ^ m_vec);

	// corr: p x q (both run over features 0..M-1), row-major (q contiguous)
	DEFINE_PROTO_STRUCT(corr_layout, q_vec ^ p_vec);

	// 1D vectors over features (dimension 'm')
	DEFINE_PROTO_STRUCT(vec_layout, m_vec);
} tuning;


// initialization function
// float_n <- N (number of rows in data)
// data[i][j] = (DATA_TYPE)(i*j)/M + i;
void init_array(num_t &float_n, auto data) {
	using namespace noarr;

	// Cache lengths once; they are constant for the whole run
	const num_t N_len = static_cast<num_t>(data | get_length<'n'>());
	const num_t M_len = static_cast<num_t>(data | get_length<'m'>());

	float_n = N_len;

	// Traversal order is column-major (m outer, n inner), but we only care
	// about the logical indices here; layout is abstracted by Noarr.
	traverser(data).for_each([=](auto state) {
		auto [i, j] = get_indices<'n', 'm'>(state);

		data[state] = static_cast<num_t>(
			static_cast<num_t>(i * j) / M_len + static_cast<num_t>(i)
		);
	});
}


// main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_correlation(num_t float_n, auto data, auto corr, auto mean, auto stddev) {
	using namespace noarr;

	const num_t eps         = SCALAR_VAL(0.1);
	const num_t inv_float_n = SCALAR_VAL(1.0) / float_n;
	const num_t inv_sqrt_n  = SCALAR_VAL(1.0) / SQRT_FUN(float_n);

#pragma scop

	// ------------------------------------------------------------------------
	// Phase 1: column means
	//   mean[m] = (1/N) * sum_n data[n][m]
	//
	// With the column-major layout (n contiguous), traversing with 'm' fixed
	// and iterating over 'n' gives unit-stride access and good cache behavior.
	// ------------------------------------------------------------------------
	traverser(data, mean).template for_dims<'m'>([=](auto trav_m) {
		// trav_m has 'm' fixed (one feature column)
		auto state_m = trav_m.state();

		mean[state_m] = SCALAR_VAL(0.0);

		trav_m.for_each([=](auto state) {
			// state has 'n' and 'm'; mean ignores 'n'
			mean[state] += data[state];
		});

		// Scale by 1/N (precomputed as inv_float_n)
		mean[state_m] *= inv_float_n;
	});

	// ------------------------------------------------------------------------
	// Phase 2: column standard deviations
	//
	//   stddev[m] = sqrt( (1/N) * sum_n (data[n,m] - mean[m])^2 )
	//   if stddev[m] <= eps then stddev[m] = 1.0
	//
	// We then overwrite stddev[m] with the *scaling factor*
	//
	//   scale[m] = 1 / (sqrt(float_n) * stddev[m])
	//
	// so that normalization can be implemented as a multiply instead of
	// a divide, reusing the stddev vector for scale to avoid extra storage.
	// ------------------------------------------------------------------------
	traverser(data, mean, stddev).template for_dims<'m'>([=](auto trav_m) {
		auto state_m = trav_m.state();

		stddev[state_m] = SCALAR_VAL(0.0);

		trav_m.for_each([=](auto state) {
			num_t val = data[state] - mean[state];
			stddev[state] += val * val;
		});

		// Finish variance and take sqrt
		stddev[state_m] *= inv_float_n;
		num_t sigma = SQRT_FUN(stddev[state_m]);

		// Epsilon guard as in the original code
		if (sigma <= eps)
			sigma = SCALAR_VAL(1.0);

		// Reuse stddev[m] as a per-feature scaling factor:
		//   scale[m] = 1 / (sqrt(float_n) * sigma)
		stddev[state_m] = inv_sqrt_n / sigma;
	});

	// ------------------------------------------------------------------------
	// Phase 3: center and scale the column vectors in-place:
	//
	// Original:
	//   data[n][m] = (data[n][m] - mean[m]) / (sqrt(float_n) * stddev[m])
	//
	// With the precomputed scale[m] stored in stddev[m]:
	//   data[n][m] = (data[n][m] - mean[m]) * stddev[m]
	//
	// We traverse column-major (m fixed, n varying) for unit-stride access.
	// ------------------------------------------------------------------------
	traverser(data, mean, stddev).template for_dims<'m'>([=](auto trav_m) {
		trav_m.for_each([=](auto state) {
			data[state] = (data[state] - mean[state]) * stddev[state];
		});
	});

	// ------------------------------------------------------------------------
	// Phase 4: compute the M x M correlation matrix:
	//
	// Given the normalized data (zero mean, unit variance per column),
	// the correlation between features p and q is simply:
	//
	//   corr[p][q] = sum_n data[n][p] * data[n][q]
	//
	// We compute only the upper triangle (p <= q) and mirror to enforce
	// symmetry. The diagonal elements corr[p][p] are set to 1.0.
	//
	// With the column-major layout for 'data', we form views where the
	// feature index matches corr's 'p'/'q', but the inner (contiguous)
	// dimension is the row index 'n'.
	// ------------------------------------------------------------------------

	// Views on data so that feature indices are 'p' and 'q'.  The inner
	// contiguous dimension is 'n', thanks to the column-major layout.
	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // dims: 'p', 'n'
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // dims: 'q', 'n'

	// Outer loop over p = 0 .. M-1 (dimension 'p')
	traverser(corr).template for_dims<'p'>([=](auto trav_p) {
		auto state_p = trav_p.state();
		auto i = noarr::get_index<'p'>(state_p);

		// Diagonal element: corr[i][i] = 1.0
		corr[noarr::idx<'p', 'q'>(i, i)] = SCALAR_VAL(1.0);

		// Inner loop over q = 0 .. M-1 (dimension 'q'), but we only
		// compute the strictly upper triangle (q > p) here.
		trav_p.template for_dims<'q'>([=](auto trav_pq) {
			auto state_pq = trav_pq.state();
			auto j = noarr::get_index<'q'>(state_pq);

			if (j > i) {
				// Accumulator for corr[i][j]
				num_t sum = SCALAR_VAL(0.0);

				// Fix 'p' and 'q' for the data views to the current (i, j)
				// and traverse over 'n'. Thanks to column-major layout,
				// this is a unit-stride dot product in 'n'.
				noarr::traverser(data_p, data_q)
					.order(noarr::fix(state_pq))
					.for_each([&](auto state_n) {
						sum += data_p[state_n] * data_q[state_n];
					});

				// Write upper triangle element
				corr[state_pq] = sum;

				// Enforce symmetry: corr[j][i] = corr[i][j]
				auto state_qp = noarr::idx<'p', 'q'>(j, i);
				corr[state_qp] = sum;
			}
		});
	});

#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
	num_t float_n;

	// set all relevant lengths
	auto set_lengths =
		noarr::set_length<'n'>(n) ^
		noarr::set_length<'m'>(m) ^
		noarr::set_length<'p'>(m) ^
		noarr::set_length<'q'>(m);

	// allocate bags for data, correlation matrix, mean, and stddev
	auto data   = noarr::bag(noarr::scalar<num_t>() ^ tuning.data_layout ^ set_lengths);
	auto corr   = noarr::bag(noarr::scalar<num_t>() ^ tuning.corr_layout ^ set_lengths);
	auto mean   = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout  ^ set_lengths);
	auto stddev = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout  ^ set_lengths);

	// initialize data
	init_array(float_n, data.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_correlation(float_n, data.get_ref(), corr.get_ref(), mean.get_ref(), stddev.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (correlation matrix) if requested
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'p' (row index) to top for a natural row-major printout
		noarr::serialize_data(std::cerr, corr.get_ref() ^ noarr::hoist<'p'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
