	// The per-column mean is loaded once into a scalar, and the sum of
	// squared differences is accumulated in a scalar.
	// ------------------------------------------------------------------------
	traverser(data, mean, stddev).template for_dims<'m'>([=](auto trav_m) {
		auto state_m = trav_m.state();

		num_t mean_j = mean[state_m];
		num_t sum_sq = SCALAR_VAL(0.0);

		trav_m.for_each([=, &sum_sq, mean_j](auto state) {
			num_t val = data[state] - mean_j;
			sum_sq += val * val;
		});

		num_t variance = sum_sq / float_n;
		num_t std = SQRT_FUN(variance);

		if (std <= eps)
			std = SCALAR_VAL(1.0);

		stddev[state_m] = std;
	});

