	// Phase 4: Compute the m x m correlation matrix:
	//
	// For normalized data (each feature column has L2 norm 1), the
	// correlation between features i and j is:
	//
	//   corr[i][j] = sum_k data[k][i] * data[k][j]
	//
	// We compute only the upper triangle (j > i) and mirror it, while
	// setting the diagonal to 1.0.
	// ------------------------------------------------------------------------

	// Create views on data so that the feature index matches corr's 'p'/'q'
	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // dims: 'p', 'n'
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // dims: 'q', 'n'

