	//   (x - mean[j]) / (sqrt(float_n) * stddev[j])
	// = (x - mean[j]) * scale[j]
	//
	// instead of a division with a repeated sqrt in the inner loop.
	// ------------------------------------------------------------------------
	traverser(stddev, scale).template for_dims<'m'>([&](auto trav_m) {
		auto state_m = trav_m.state();
		scale[state_m] = inv_sqrt_n / stddev[state_m];
	});

	// ------------------------------------------------------------------------
	// Phase 3: Center and normalize each column in-place:
	//
	//   data[i][j] = (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
	//              = (data[i][j] - mean[j]) * scale[j]
	//
	// We traverse columns 'm' outer and rows 'n' inner. With our
	// column-major layout, this sweeps each column contiguously.
	// ------------------------------------------------------------------------
	traverser(data, mean, scale).template for_dims<'m'>([&](auto trav_m) {
		// trav_m has 'm' fixed; iterate over 'n'
		trav_m.template for_each<'n'>([&](auto state) {
			data[state] = (data[state] - mean[state]) * scale[state];
		});
	});

	// ------------------------------------------------------------------------
	// Phase 4: Compute the m x m correlation matrix:
	//
	// for (i = 0; i < M-1; i++) {
	//   corr[i][i] = 1.0;
	//   for (j = i+1; j < M; j++) {
	//     corr[i][j] = sum_k data[k][i] * data[k][j];
	//     corr[j][i] = corr[i][j];
	//   }
	// }
	// corr[M-1][M-1] = 1.0;
	//
	// Here data is already centered and normalized, so each column has
	// unit L2 norm and zero mean. The correlation is exactly the dot
	// product between two columns.
	// ------------------------------------------------------------------------

	std::size_t m_len = corr | get_length<'p'>(); // M

	// Create views on data so that the feature index matches corr's 'p'/'q'
	// dimensions. The underlying layout is column-major in 'n', so the
	// reduction over 'n' for each (p,q) pair is unit-stride.
	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // dims: 'n', 'p'
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // dims: 'n', 'q'

	// Outer loop over i = 0 .. M-1 (dimension 'p')
	traverser(corr).template for_dims<'p'>([&](auto trav_p) {
		auto state_p = trav_p.state();
		auto i = noarr::get_index<'p'>(state_p);

		// Only i < M-1 participate in the nested j-loop
		if (i < m_len - 1) {
			// corr[i][i] = 1.0;
			corr[noarr::idx<'p', 'q'>(i, i)] = SCALAR_VAL(1.0);

			// Middle loop over j = 0 .. M-1 (dimension 'q'), we only use j > i
			trav_p.template for_dims<'q'>([&](auto trav_pq) {
				auto state_pq = trav_pq.state();
				auto j = noarr::get_index<'q'>(state_pq);

				if (j > i) {
					// Accumulate into a scalar register instead of updating
					// corr[p,q] on every iteration. This reduces memory
					// traffic and gives the compiler a clean reduction to
					// vectorize over 'n'.
					num_t acc = SCALAR_VAL(0.0);

					// Inner loop over k = 0 .. N-1 (dimension 'n')
					// Fix 'p' and 'q' for the data views to the current (i, j).
					noarr::traverser(data_p, data_q)
						.order(noarr::fix(state_pq))
						.for_each([&](auto state_n) {
							// state_n has 'n' (and fixed 'p','q' via fix)
							acc += data_p[state_n] * data_q[state_n];
						});

					// Write back the accumulated dot product and enforce symmetry.
					corr[state_pq] = acc;

					auto state_qp = noarr::idx<'p', 'q'>(j, i);
					corr[state_qp] = acc;
				}
			});
		}
	});

	// Final diagonal element: corr[M-1][M-1] = 1.0;
	if (m_len > 0) {
		auto last = m_len - 1;
		corr[noarr::idx<'p', 'q'>(last, last)] = SCALAR_VAL(1.0);
	}

#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
