[[gnu::flatten, gnu::noinline]]
void kernel_correlation(num_t float_n, auto data, auto corr, auto mean, auto stddev) {
	using namespace noarr;

	// Small epsilon used to clamp very small standard deviations
	const num_t eps = SCALAR_VAL(0.1);

	// Precompute invariants once:
	//   inv_float_n = 1 / N
	//   sqrt_n      = sqrt(N)
	//   inv_sqrt_n  = 1 / sqrt(N)
	const num_t inv_float_n = SCALAR_VAL(1.0) / float_n;
	const num_t sqrt_n      = SQRT_FUN(float_n);
	const num_t inv_sqrt_n  = SCALAR_VAL(1.0) / sqrt_n;

#pragma scop

	// ------------------------------------------------------------------------
	// Phase 1: mean[j] = (1/N) * sum_i data[i][j]
	//
	// We traverse column by column:
	//  - outer traversal fixes 'm' (one feature)
	//  - inner traversal runs over 'n' (all samples)
	// With the chosen layout (n contiguous), each inner loop streams a
	// contiguous column data[*,m].
	// ------------------------------------------------------------------------
	traverser(data, mean).template for_dims<'m'>([=](auto trav_m) {
		// trav_m has 'm' fixed (one feature column)
		auto state_m = trav_m.state();

		// Accumulate in a scalar to avoid repeated loads/stores of mean[state_m]
		num_t sum = SCALAR_VAL(0.0);

		trav_m.for_each([&](auto state) {
			// state has 'n' and 'm'; mean ignores 'n'
			sum += data[state];
		});

		mean[state_m] = sum * inv_float_n;
	});

	// ------------------------------------------------------------------------
	// Phase 2: stddev[j] = sqrt( (1/N) * sum_i (data[i][j] - mean[j])^2 )
	//            stddev[j] = 1.0 if stddev[j] <= eps
	//
	// Same traversal pattern as for the mean: iterate columns, reduce over rows.
	// ------------------------------------------------------------------------
	traverser(data, mean, stddev).template for_dims<'m'>([=](auto trav_m) {
		auto state_m = trav_m.state();

		num_t sum_sq = SCALAR_VAL(0.0);

		trav_m.for_each([&](auto state) {
			num_t val = data[state] - mean[state];
			sum_sq += val * val;
		});

		num_t var   = sum_sq * inv_float_n;
		num_t sigma = SQRT_FUN(var);
		if (sigma <= eps)
			sigma = SCALAR_VAL(1.0);

		stddev[state_m] = sigma;
	});

	// ------------------------------------------------------------------------
	// Phase 2b: precompute per-feature scaling factor
	//
	//   scale[j] = 1 / (sqrt(float_n) * stddev[j])
	//
	// Instead of keeping a separate scale[] array, we overwrite stddev[] with
	// scale[]. The original stddev[] is not observed outside this kernel, and
	// normalization only needs the combined factor 1/(sqrt_n * stddev[j]).
	// ------------------------------------------------------------------------
	traverser(stddev).for_each([=](auto state_m) {
		num_t sigma = stddev[state_m];
		num_t scale = inv_sqrt_n / sigma; // = 1 / (sqrt_n * sigma)
		stddev[state_m] = scale;
	});

	// ------------------------------------------------------------------------
	// Phase 3: Center and reduce the column vectors:
	//   data[i][j] = (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
	//               = (data[i][j] - mean[j]) * scale[j]
	//
	// We again traverse column-wise for good locality:
	//   - outer traversal fixes 'm'
	//   - inner traversal iterates 'n', streaming data[*,m]
	// ------------------------------------------------------------------------
	traverser(data, mean, stddev).template for_dims<'m'>([=](auto trav_m) {
		trav_m.for_each([=](auto state) {
			// stddev[state] now holds scale[j]
			data[state] = (data[state] - mean[state]) * stddev[state];
		});
	});

	// ------------------------------------------------------------------------
	// Phase 4: Compute the m x m correlation matrix:
	//
	// for (i = 0; i < M-1; i++) {
	//   corr[i][i] = 1.0;
	//   for (j = i+1; j < M; j++) {
	//     corr[i][j] = sum_k data[k][i] * data[k][j];
	//     corr[j][i] = corr[i][j];
	//   }
	// }
	// corr[M-1][M-1] = 1.0;
	//
