	//   - use column-major data so each dot product traverses contiguous data[*,i]
	//   - accumulate into a local scalar and store corr[i][j] once, instead of
	//     updating corr[i][j] inside the innermost loop.
	// ------------------------------------------------------------------------

	std::size_t m_len = corr | get_length<'p'>(); // M

