	// data_p: dims 'n','p', data_q: dims 'n','q'
	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // column i
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // column j

